 grp int:=(n%5)::int; lg int; r bigint; pool jsonb; kind jsonb; title jsonb; leagues jsonb:='[]'::jsonb;
begin
 -- The kind of play is the same for everyone this hour (fields, crops, buildings, market, helping out; in the village mine and
 -- forest, fields and kitchens, workshops, market square, around the village). 24 is not a multiple of 5, so an hour of the day
 -- gets another kind every day.
 for lg in 0..jsonb_array_length(pools)-1 loop
  pool:=pools->lg->grp;
  r:=abs(hashtextextended('harvest-hour-event:'||n||':'||lg,0));
  kind:=pool->((r%jsonb_array_length(pool))::int);
  title:=kind->'titles'->(((r/7)%jsonb_array_length(kind->'titles'))::int);
  leagues:=leagues||jsonb_build_array(jsonb_build_object('title',title->>0,'description',title->>1,
   'objectives',jsonb_build_array(jsonb_build_object('stat',kind->>'stat','target',(kind->>'target')::int))));
 end loop;
 -- The event's own title and goal are the Sprout League's: admin screens and any older reader keep working.
 return jsonb_build_object('title',leagues->0->>'title','description',leagues->0->>'description','objectives',leagues->0->'objectives','leagues',leagues);
end $function$;

-- After-check: both exactly as generated, and the chest still security definer with an empty search_path.
do $check$ declare m text; d boolean; c text[]; begin
 select md5(p.prosrc) into m from pg_proc p where p.oid='public.harvest_family_chest()'::regprocedure;
 if m is distinct from '678808194bae9a2272f4267a9b0d600a' then raise exception 'After-check: public.harvest_family_chest() is %, not 678808194bae9a2272f4267a9b0d600a', m; end if;
 select md5(p.prosrc) into m from pg_proc p where p.oid='public.harvest_event_pick(bigint)'::regprocedure;
 if m is distinct from 'f2998fc6536299b3c248254eec3c9e33' then raise exception 'After-check: public.harvest_event_pick(bigint) is %, not f2998fc6536299b3c248254eec3c9e33', m; end if;
 select p.prosecdef, p.proconfig into d, c from pg_proc p where p.oid='public.harvest_family_chest()'::regprocedure;
 if not d or c is distinct from array['search_path=""'] then raise exception 'After-check: harvest_family_chest lost security definer or its search_path'; end if;
end $check$;

commit;
